"use server";

import { revalidatePath } from "next/cache";
import {
  addBook,
  deleteBook,
  markBookFinished,
  updateBook,
  type BookStatus,
} from "@/lib/books";

export async function createBookAction(formData: FormData) {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();
  const statusRaw = String(formData.get("status") ?? "reading");
  const status: BookStatus = statusRaw === "finished" ? "finished" : "reading";

  if (!title || !author) {
    throw new Error("Title and author are required");
  }

  const book = await addBook({ title, author, notes, status });
  revalidatePath("/");
  revalidatePath(`/books/${book.id}`);
  return book;
}

export async function finishBookAction(id: string) {
  const updated = await markBookFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  return updated;
}

export async function toggleBookStatusAction(id: string, status: BookStatus) {
  const updated = await updateBook(id, { status });
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  return updated;
}

export async function updateBookNotesAction(id: string, formData: FormData) {
  const notes = String(formData.get("notes") ?? "");
  const updated = await updateBook(id, { notes });
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
  return updated;
}

export async function removeBookAction(id: string) {
  await deleteBook(id);
  revalidatePath("/");
}

