"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { createBookAction } from "@/app/actions";

export function AddBookForm() {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [notes, setNotes] = useState("");
  const [status, setStatus] = useState<"reading" | "finished">("reading");
  const [error, setError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);

    if (!title.trim() || !author.trim()) {
      setError("Please enter both a title and an author.");
      return;
    }

    const formData = new FormData();
    formData.set("title", title.trim());
    formData.set("author", author.trim());
    formData.set("notes", notes.trim());
    formData.set("status", status);

    startTransition(async () => {
      try {
        await createBookAction(formData);
        setTitle("");
        setAuthor("");
        setNotes("");
        setStatus("reading");
        router.refresh();
      } catch (err) {
        setError(err instanceof Error ? err.message : "Could not add book");
      }
    });
  }

  return (
    <section className="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading" className="section-title" style={{ marginBottom: "0.85rem" }}>
        Add a Book
      </h2>
      <form onSubmit={handleSubmit} className="form-grid">
        <div className="form-row">
          <div>
            <label htmlFor="book-title">Title</label>
            <input
              id="book-title"
              name="title"
              type="text"
              placeholder="e.g. Project Hail Mary"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>
          <div>
            <label htmlFor="book-author">Author</label>
            <input
              id="book-author"
              name="author"
              type="text"
              placeholder="e.g. Andy Weir"
              value={author}
              onChange={(e) => setAuthor(e.target.value)}
              required
            />
          </div>
        </div>

        <div>
          <label htmlFor="book-notes">Notes</label>
          <textarea
            id="book-notes"
            name="notes"
            placeholder="Thoughts, favorite quotes, or why you picked it up..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "1rem", flexWrap: "wrap" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <label htmlFor="book-status" style={{ marginBottom: 0 }}>
              Status:
            </label>
            <select
              id="book-status"
              name="status"
              value={status}
              onChange={(e) => setStatus(e.target.value as "reading" | "finished")}
              style={{ width: "auto" }}
            >
              <option value="reading">Currently Reading</option>
              <option value="finished">Finished</option>
            </select>
          </div>

          <button type="submit" className="btn btn-primary" disabled={isPending}>
            {isPending ? "Adding..." : "Add Book"}
          </button>
        </div>

        {error && (
          <p role="alert" style={{ color: "#dc2626", margin: 0, fontSize: "0.875rem" }}>
            {error}
          </p>
        )}
      </form>
    </section>
  );
}

