"use client";

import { useTransition } from "react";
import { useRouter } from "next/navigation";
import { finishBookAction } from "@/app/actions";

export function MarkFinishedButton({ bookId, bookTitle }: { bookId: string; bookTitle: string }) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  function handleMarkFinished() {
    startTransition(async () => {
      await finishBookAction(bookId);
      router.refresh();
    });
  }

  return (
    <button
      type="button"
      onClick={handleMarkFinished}
      disabled={isPending}
      className="btn btn-secondary"
      aria-label={`Mark ${bookTitle} as finished`}
    >
      {isPending ? "Saving..." : "Mark as Finished"}
    </button>
  );
}

