"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toggleBookStatusAction, updateBookNotesAction } from "@/app/actions";
import type { Book } from "@/lib/books";

export function BookDetailControls({ book }: { book: Book }) {
  const router = useRouter();
  const [notes, setNotes] = useState(book.notes);
  const [savedMessage, setSavedMessage] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isPending, startTransition] = useTransition();

  function handleStatusToggle() {
    const nextStatus = book.status === "reading" ? "finished" : "reading";
    startTransition(async () => {
      await toggleBookStatusAction(book.id, nextStatus);
      router.refresh();
    });
  }

  function handleNotesSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setSavedMessage(false);
    const formData = new FormData();
    formData.set("notes", notes);

    startTransition(async () => {
      await updateBookNotesAction(book.id, formData);
      setSavedMessage(true);
      router.refresh();
    });
  }

  async function handleCopyLink() {
    const url = window.location.href;
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(url);
      setCopied(true);
