import Link from "next/link";
import { getBooks } from "@/lib/books";
import { AddBookForm } from "./components/AddBookForm";
import { MarkFinishedButton } from "./components/MarkFinishedButton";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const books = await getBooks();
  const currentlyReading = books.filter((b) => b.status === "reading");
  const finishedBooks = books.filter((b) => b.status === "finished");

  return (
    <div>
      <AddBookForm />

      <section className="section" aria-labelledby="currently-reading-heading">
        <div className="section-header">
          <h2 id="currently-reading-heading" className="section-title">
            Currently Reading
          </h2>
          <span className="badge badge-reading">{currentlyReading.length}</span>
        </div>

        {currentlyReading.length === 0 ? (
          <div className="empty-state">
            No books currently in progress. Add a book above to start reading!
          </div>
        ) : (
          <ul className="book-list" data-testid="currently-reading-list">
            {currentlyReading.map((book) => (
              <li key={book.id} className="card book-item">
                <Link href={`/books/${book.id}`} className="book-link">
                  <h3 className="book-title">{book.title}</h3>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                </Link>
                <div className="book-actions">
                  <MarkFinishedButton bookId={book.id} bookTitle={book.title} />
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="section" aria-labelledby="finished-books-heading">
        <div className="section-header">
          <h2 id="finished-books-heading" className="section-title">
            Finished
          </h2>
          <span className="badge badge-finished">{finishedBooks.length}</span>
        </div>

        {finishedBooks.length === 0 ? (
          <div className="empty-state">You haven&apos;t marked any books as finished yet.</div>
        ) : (
          <ul className="book-list" data-testid="finished-books-list">
            {finishedBooks.map((book) => (
              <li key={book.id} className="card book-item">
                <Link href={`/books/${book.id}`} className="book-link">
                  <h3 className="book-title">{book.title}</h3>
                  <p className="book-author">by {book.author}</p>
                  {book.notes && <p className="book-notes-preview">{book.notes}</p>}
                </Link>
                <div className="book-actions">
                  <span className="badge badge-finished">Finished</span>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

