import { describe, it, expect, beforeEach, afterEach } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import os from "node:os";
import {
  addBook,
  getBookById,
  getBooks,
  markBookFinished,
  updateBook,
  deleteBook,
} from "../lib/books";

describe("Books JSON storage", () => {
  let tempDir: string;
  let testFilePath: string;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "books-test-"));
    testFilePath = path.join(tempDir, "books.json");
  });

  afterEach(async () => {
    await fs.rm(tempDir, { recursive: true, force: true });
  });

  it("initializes with default books if file does not exist", async () => {
    const books = await getBooks(testFilePath);
    expect(books.length).toBeGreaterThanOrEqual(2);
    expect(books.some((b) => b.status === "reading")).toBe(true);
    expect(books.some((b) => b.status === "finished")).toBe(true);
  });

  it("adds a book and persists it to the JSON file across reads", async () => {
    const added = await addBook(
      {
        title: "Clean Code",
        author: "Robert C. Martin",
        notes: "Focus on readable functions.",
      },
      testFilePath
    );

    expect(added.id).toBeDefined();
    expect(added.title).toBe("Clean Code");
    expect(added.author).toBe("Robert C. Martin");
    expect(added.notes).toBe("Focus on readable functions.");
    expect(added.status).toBe("reading");

    const fetched = await getBookById(added.id, testFilePath);
    expect(fetched).toEqual(added);

    const rawFile = JSON.parse(await fs.readFile(testFilePath, "utf8"));
    expect(rawFile.some((b: { id: string }) => b.id === added.id)).toBe(true);
  });

  it("marks a book as finished and updates notes", async () => {
    const added = await addBook(
      {
        title: "Dune",
        author: "Frank Herbert",
        notes: "Initial note",
      },
      testFilePath
    );

    const finished = await markBookFinished(added.id, testFilePath);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toBeDefined();

    const updatedNotes = await updateBook(
      added.id,
      { notes: "Fear is the mind-killer." },
      testFilePath
    );
    expect(updatedNotes?.notes).toBe("Fear is the mind-killer.");

    const reloaded = await getBookById(added.id, testFilePath);
    expect(reloaded?.status).toBe("finished");
    expect(reloaded?.notes).toBe("Fear is the mind-killer.");
  });

  it("deletes a book from storage", async () => {
    const added = await addBook(
      {
        title: "Temporary Book",
        author: "Test Author",
      },
      testFilePath
    );

    const deleted = await deleteBook(added.id, testFilePath);
    expect(deleted).toBe(true);
    expect(await getBookById(added.id, testFilePath)).toBeUndefined();
  });
});

