import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";

export type BookStatus = "reading" | "finished";

export interface Book {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: BookStatus;
  createdAt: string;
  finishedAt?: string;
}

export interface CreateBookInput {
  title: string;
  author: string;
  notes?: string;
  status?: BookStatus;
}

export interface UpdateBookInput {
  title?: string;
  author?: string;
  notes?: string;
  status?: BookStatus;
}

const DEFAULT_DATA_PATH = path.join(process.cwd(), "data", "books.json");

export function getDataFilePath(): string {
  return process.env.BOOKS_DATA_FILE || DEFAULT_DATA_PATH;
}

const INITIAL_BOOKS: Book[] = [
  {
    id: "the-pragmatic-programmer",
    title: "The Pragmatic Programmer",
    author: "Andrew Hunt & David Thomas",
    notes: "Great reminders on tracer bullets, DRY, and orthogonal design.",
    status: "reading",
    createdAt: "2025-01-10T10:00:00.000Z",
  },
  {
    id: "designing-data-intensive-applications",
    title: "Designing Data-Intensive Applications",
    author: "Martin Kleppmann",
    notes: "Essential deep dive into replication, partitioning, and consensus.",
    status: "finished",
    createdAt: "2025-01-02T09:00:00.000Z",
    finishedAt: "2025-01-09T18:00:00.000Z",
  },
];

async function ensureDataFile(filePath: string): Promise<void> {
  const dir = path.dirname(filePath);
  await fs.mkdir(dir, { recursive: true });
  try {
    await fs.access(filePath);
  } catch {
    await fs.writeFile(filePath, JSON.stringify(INITIAL_BOOKS, null, 2), "utf8");
  }
}

export async function getBooks(filePath: string = getDataFilePath()): Promise<Book[]> {
  await ensureDataFile(filePath);
  try {
    const raw = await fs.readFile(filePath, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export async function saveBooks(
  books: Book[],
  filePath: string = getDataFilePath()
): Promise<void> {
  const dir = path.dirname(filePath);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(filePath, JSON.stringify(books, null, 2), "utf8");
}

export async function getBookById(
  id: string,
  filePath: string = getDataFilePath()
): Promise<Book | undefined> {
  const books = await getBooks(filePath);
  return books.find((b) => b.id === id);
}

export async function addBook(
  input: CreateBookInput,
  filePath: string = getDataFilePath()
): Promise<Book> {
  const title = input.title?.trim();
  const author = input.author?.trim();
  if (!title) {
    throw new Error("Title is required");
  }
  if (!author) {
    throw new Error("Author is required");
  }

  const books = await getBooks(filePath);
  const status: BookStatus = input.status === "finished" ? "finished" : "reading";
  const now = new Date().toISOString();

  const newBook: Book = {
    id: crypto.randomUUID(),
    title,
    author,
    notes: (input.notes ?? "").trim(),
    status,
    createdAt: now,
    ...(status === "finished" ? { finishedAt: now } : {}),
  };

  books.unshift(newBook);
  await saveBooks(books, filePath);
  return newBook;
}

export async function updateBook(
  id: string,
  updates: UpdateBookInput,
  filePath: string = getDataFilePath()
): Promise<Book | null> {
  const books = await getBooks(filePath);
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) {
    return null;
  }

  const current = books[index];
  const nextStatus: BookStatus =
    updates.status === "finished" || updates.status === "reading"
      ? updates.status
      : current.status;

  let finishedAt = current.finishedAt;
  if (nextStatus === "finished" && current.status !== "finished") {
    finishedAt = new Date().toISOString();
  } else if (nextStatus === "reading") {
    finishedAt = undefined;
  }

  const updated: Book = {
    ...current,
    title: updates.title !== undefined ? updates.title.trim() || current.title : current.title,
    author: updates.author !== undefined ? updates.author.trim() || current.author : current.author,
    notes: updates.notes !== undefined ? updates.notes : current.notes,
    status: nextStatus,
    ...(finishedAt ? { finishedAt } : {}),
  };
  if (!finishedAt) {
    delete updated.finishedAt;
  }

  books[index] = updated;
  await saveBooks(books, filePath);
  return updated;
}

export async function markBookFinished(
  id: string,
  filePath: string = getDataFilePath()
): Promise<Book | null> {
  return updateBook(id, { status: "finished" }, filePath);
}

export async function deleteBook(
  id: string,
  filePath: string = getDataFilePath()
): Promise<boolean> {
  const books = await getBooks(filePath);
  const filtered = books.filter((b) => b.id !== id);
  if (filtered.length === books.length) {
    return false;
  }
  await saveBooks(filtered, filePath);
  return true;
}

